  var legacy=CardTableWorkbook.Cells(copy.rows[0]).Take(7).ToArray();var legacyPlan=w.Preview(new[]{legacy},false);Check(legacyPlan.Changes[0].After.additionalEffects.Length==2,"old 7 columns preserve compound configuration");
  var setup=new GameSetup();setup.CardEffects.Add(new CardEffectSpec{Name="sentinel"});Reject(()=>copy.Apply(setup),"unintegrated compound player runtime blocked");Check(setup.CardEffects.Count==1&&setup.CardEffects[0].Name=="sentinel","unsupported compound does not partially clear player setup");
  var enemyCopy=ScriptableObject.CreateInstance<EnemyCardTable>();enemyCopy.rows=new[]{compound.Copy()};setup.EnemySkills.Add(new EnemySkill{Name="sentinel"});Reject(()=>enemyCopy.Apply(setup),"unintegrated compound enemy runtime blocked");Check(setup.EnemySkills.Count==1&&setup.EnemySkills[0].Name=="sentinel","enemy setup atomic");
