  Check(Json(p)==playerBefore&&Json(e)==enemyBefore,"default player and enemy tables untouched");AssetDatabase.DeleteAsset("Assets/RainbowLi/Data/CardToolsTest.asset");UnityEngine.Object.DestroyImmediate(w);UnityEngine.Object.DestroyImmediate(enemyCopy);UnityEngine.Object.DestroyImmediate(cardDef);
  EditorSceneManager.OpenScene("Assets/RainbowLi/Scenes/RainbowLiGame.unity");start=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;EditorApplication.EnterPlaymode();
 }catch(Exception ex){Console.WriteLine("CARD TOOLS FAILED: "+ex);EditorApplication.Exit(1);}}
 static void Log(string s,string stack,LogType t){if(stack.Contains("UnityEditor.Search.SearchDatabase"))return;if(t==LogType.Error||t==LogType.Exception){Console.WriteLine("CARD TOOLS FAILED: "+s+stack);EditorApplication.Exit(1);}}
 static void Tick(){try{if(EditorApplication.timeSinceStartup-start>60)throw new Exception("play timeout");if(!EditorApplication.isPlaying)return;var v=UnityEngine.Object.FindFirstObjectByType<GameView>();if(v==null||!v.IsReady)return;var g=v.session.Game;Check(g.Deck.Count==18&&g.Deck.All(c=>c.Spec!=null),"native player default still generates 18 configured cards");Check(Enumerable.Range(1,6).All(n=>g.Deck.Count(c=>c.Number==n)==3),"original 3 digit groups preserved");g.StartBattle();v.session.Notify();Check(g.Timeline.All(a=>a.EffectSpec!=null),"native enemy intents still use independent table");Check(CardMotionController.TargetsEnemy(new BattleAction{Effect=CardEffect.Poison})&&!CardMotionController.TargetsEnemy(new BattleAction{Enemy=true,Effect=CardEffect.Poison}),"polarity does not invert opponent target");Console.WriteLine("PASS: "+checks+" card tools, workbook compatibility, diff, errors, bulk Undo, compound contract and native integration checks.");EditorApplication.update-=Tick;EditorApplication.Exit(0);}catch(Exception ex){Console.WriteLine("CARD TOOLS FAILED: "+ex);EditorApplication.Exit(1);}}
}
